#include <limits.h>

typedef struct {
    int u, v, w;
} Edge;

typedef struct {
    long long dist;
    int vertex;
} HeapNode;

static int E, R;
static int head[10005], to[40005], weight[40005], nextArc[40005], arcId[40005];
static Edge edges[20005];
static int timerValue, tin[10005], low[10005], bridge[20005];

static void findBridges(int u, int parentEdge) {
    tin[u] = low[u] = ++timerValue;

    for (int a = head[u]; a != -1; a = nextArc[a]) {
        int id = arcId[a];
        if (id == parentEdge) continue;

        int v = to[a];
        if (tin[v]) {
            if (tin[v] < low[u]) low[u] = tin[v];
        } else {
            findBridges(v, id);
            if (low[v] < low[u]) low[u] = low[v];
            if (low[v] > tin[u]) bridge[id] = 1;
        }
    }
}

static int dsu[10005];

static int findSet(int x) {
    if (dsu[x] != x) dsu[x] = findSet(dsu[x]);
    return dsu[x];
}

static void unionSets(int a, int b) {
    a = findSet(a);
    b = findSet(b);
    if (a != b) dsu[b] = a;
}

static HeapNode heap[50000];
static int heapSize;

static void pushHeap(long long dist, int vertex) {
    int i = ++heapSize;
    while (i > 1 && heap[i / 2].dist > dist) {
        heap[i] = heap[i / 2];
        i /= 2;
    }
    heap[i].dist = dist;
    heap[i].vertex = vertex;
}

static HeapNode popHeap(void) {
    HeapNode result = heap[1];
    HeapNode last = heap[heapSize--];
    int i = 1;

    while (i * 2 <= heapSize) {
        int child = i * 2;
        if (child + 1 <= heapSize && heap[child + 1].dist < heap[child].dist)
            child++;
        if (heap[child].dist >= last.dist) break;
        heap[i] = heap[child];
        i = child;
    }
    heap[i] = last;
    return result;
}

static long long dist[10005];

int main(void) {
    int V;
    if (scanf("%d %d", &V, &R) != 2) return 0;

    for (int i = 1; i <= V; i++) head[i] = -1;

    int arcCount = 0;
    for (int i = 0; i < R; i++) {
        int a, b, c;
        scanf("%d %d %d", &a, &b, &c);
        edges[i] = (Edge){a, b, c};

        to[arcCount] = b;
        weight[arcCount] = c;
        arcId[arcCount] = i;
        nextArc[arcCount] = head[a];
        head[a] = arcCount++;

        to[arcCount] = a;
        weight[arcCount] = c;
        arcId[arcCount] = i;
        nextArc[arcCount] = head[b];
        head[b] = arcCount++;
    }

    for (int i = 1; i <= V; i++) {
        if (!tin[i]) findBridges(i, -1);
    }

    for (int i = 1; i <= V; i++) dsu[i] = i;
    for (int i = 0; i < R; i++) {
        if (!bridge[i]) unionSets(edges[i].u, edges[i].v);
    }

    long long cycleLength[10005] = {0};
    for (int i = 0; i < R; i++) {
        if (!bridge[i])
            cycleLength[findSet(edges[i].u)] += edges[i].w;
    }

    int K;
    scanf("%d", &K);

    while (K--) {
        int source;
        long long trainLength;
        scanf("%d %lld", &source, &trainLength);

        for (int i = 1; i <= V; i++) dist[i] = LLONG_MAX;
        dist[source] = 0;
        heapSize = 0;
        pushHeap(0, source);

        while (heapSize) {
            HeapNode cur = popHeap();
            int u = cur.vertex;
            if (cur.dist != dist[u]) continue;

            for (int a = head[u]; a != -1; a = nextArc[a]) {
                int v = to[a];
                long long nd = cur.dist + weight[a];
                if (nd < dist[v]) {
                    dist[v] = nd;
                    pushHeap(nd, v);
                }
            }
        }

        long long answer = LLONG_MAX;
        for (int v = 1; v <= V; v++) {
            int root = findSet(v);
            if (cycleLength[root] >= trainLength && dist[v] != LLONG_MAX) {
                long long candidate = cycleLength[root] + 2 * dist[v];
                if (candidate < answer) answer = candidate;
            }
        }

        if (answer == LLONG_MAX) printf("-1\n");
        else printf("%lld\n", answer);
    }

    return 0;
}
